import { create } from "zustand";import { persist } from "zustand/middleware";
function getProductId(product){return product.id||product.productId;}
export const useCartStore=create(persist((set,get)=>({items:[],addItem:(product,availableQuantity=1)=>{const productId=getProductId(product);if(!productId||availableQuantity<=0)return;const existing=get().items.find(i=>i.productId===productId);if(existing){set({items:get().items.map(i=>i.productId===productId?{...i,quantity:Math.min(i.quantity+1,availableQuantity),availableQuantity}:i)});return;}set({items:[...get().items,{productId,name:product.name,price:Number(product.price||0),currency:product.currency||"INR",imageUrl:product.imageUrl||product.image,quantity:1,availableQuantity}]});},increaseQuantity:(id)=>set({items:get().items.map(i=>i.productId===id?{...i,quantity:Math.min(i.quantity+1,i.availableQuantity)}:i)}),decreaseQuantity:(id)=>set({items:get().items.map(i=>i.productId===id?{...i,quantity:i.quantity-1}:i).filter(i=>i.quantity>0)}),removeItem:(id)=>set({items:get().items.filter(i=>i.productId!==id)}),clearCart:()=>set({items:[]})}),{name:"boutique-cart",version:2,migrate:()=>({items:[]})}));
export const getCartItemCount=items=>items.reduce((t,i)=>t+i.quantity,0);export const getCartTotal=items=>items.reduce((t,i)=>t+Number(i.price||0)*i.quantity,0);
